  assert(typeof db.exec==='function'&&typeof db.prepare==='function','Use an explicit SQLite database for isolated core execution.');db.exec('PRAGMA journal_mode=WAL; PRAGMA foreign_keys=ON; CREATE TABLE IF NOT EXISTS client_template_state(id INTEGER PRIMARY KEY CHECK(id=1),json TEXT NOT NULL); CREATE TABLE IF NOT EXISTS client_template_blobs(sha256 TEXT PRIMARY KEY,size INTEGER NOT NULL,bytes BLOB NOT NULL)');
